<?php
require_once __DIR__ . '/scm_helpers.php';
$user=require_scm_admin();$pdo=db();$method=$_SERVER['REQUEST_METHOD'];
if($method==='GET'){$cfg=$pdo->query("SELECT * FROM scm_configuracion WHERE id=1")->fetch();$counts=[];$counts['productos']=(int)$pdo->query("SELECT COUNT(*) FROM productos WHERE estado='activo'")->fetchColumn();$counts['proveedores']=(int)$pdo->query("SELECT COUNT(*) FROM proveedores WHERE estado='activo'")->fetchColumn();$counts['movimientos']=(int)$pdo->query("SELECT COUNT(*) FROM movimientos_inventario")->fetchColumn();$counts['estrategias']=(int)$pdo->query("SELECT COUNT(DISTINCT estrategia_logistica) FROM productos WHERE estado='activo'")->fetchColumn();$counts['pedidos']=(int)$pdo->query("SELECT COUNT(*) FROM pedidos")->fetchColumn();$check=['productos_proveedores'=>$counts['productos']>0&&$counts['proveedores']>0,'inventario'=>$counts['productos']>0,'trazabilidad'=>$counts['movimientos']>0,'push_pull'=>$counts['estrategias']>=2,'reportes'=>$counts['productos']>0];json_response(['estado'=>$cfg,'checklist'=>$check,'conteos'=>$counts]);}
if($method==='PUT'){$d=body_json();$nivel=clean_string($d['nivel_scm']??'');$desc=clean_string($d['descripcion']??'');if(!in_array($nivel,['Inicial','En desarrollo','Optimizado'],true))json_response(['error'=>'Nivel SCM inválido.'],422);$pdo->prepare("UPDATE scm_configuracion SET nivel_scm=?,descripcion=?,actualizado_por=? WHERE id=1")->execute([$nivel,$desc,$user['id']]);json_response(['ok'=>true,'mensaje'=>'Nivel SCM actualizado.']);}
json_response(['error'=>'Método no permitido.'],405);
